#include <stdio.h>

void print_binary(unsigned int num) {
    // Handle the special case of 0
    if (num == 0) {
        printf("0");
        return;
    }

    // Determine the number of bits needed (assuming 32-bit unsigned int)
    unsigned int mask = 1u << (sizeof(unsigned int) * 8 - 1);

    // Print each bit from MSB to LSB
    for (int i = 0; i < sizeof(unsigned int) * 8; i++) {
        // Check if the current bit is set
        if (num & mask) {
            printf("1");
        } else {
            printf("0");
        }

        // Shift the mask to the right for the next bit
        mask >>= 1;

        // Add space between bits for readability (optional)
        if (i < sizeof(unsigned int) * 8 - 1) {
            printf(" ");
        }
    }
}

int main(void) {
    unsigned int num;

    printf("Enter an unsigned integer: ");
    scanf("%u", &num);

    printf("Binary representation: ");
    print_binary(num);
    printf("\n");

    return 0;
}

