char* safe_concatenate(const char* str1, const char* str2) {
    // Calculate the total length needed (including null terminator)
    size_t len1 = strlen(str1);
    size_t len2 = strlen(str2);
    size_t total_len = len1 + len2 + 1; // +1 for null terminator

    // Allocate memory
    char* result = malloc(total_len);
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Copy strings into the buffer
    strcpy(result, str1);
    strcat(result, str2);

    return result;
}

int main() {
    const char* str1 = "Hello, ";
    const char* str2 = "world!";

    char* concatenated = safe_concatenate(str1, str2);

    if (concatenated != NULL) {
        printf("Concatenated string: %s\n", concatenated);
        free(concatenated); // Don't forget to free the allocated memory
    }

    return 0;
}

