#include <stdio.h>
#include <stdbool.h>
#include <assert.h>

#define STACK_SIZE 5

typedef struct {
    int items[STACK_SIZE];
    int top;
} Stack;

// Initialize the stack
void stack_init(Stack *s) {
    s->top = -1; // Empty stack
}

// Check if stack is full
bool stack_is_full(const Stack *s) {
    return s->top == STACK_SIZE - 1;
}

// Check if stack is empty
bool stack_is_empty(const Stack *s) {
    return s->top == -1;
}

// Push an item onto the stack
bool stack_push(Stack *s, int value) {
    if (stack_is_full(s)) {
        return false; // Stack is full
    }
    s->items[++(s->top)] = value;
    return true;
}

// Pop an item from the stack
bool stack_pop(Stack *s, int *value) {
    if (stack_is_empty(s)) {
        return false; // Stack is empty
    }
    *value = s->items[(s->top)--];
    return true;
}

// Peek at the top item without removing it
bool stack_peek(const Stack *s, int *value) {
    if (stack_is_empty(s)) {
        return false;
    }
    *value = s->items[s->top];
    return true;
}

// Print the stack contents
void stack_print(const Stack *s) {
    printf("Stack (top to bottom): ");
    for (int i = s->top; i >= 0; i--) {
        printf("%d ", s->items[i]);
    }
    printf("\n");
}

int main() {
    Stack my_stack;
    stack_init(&my_stack);

    printf("Stack demonstration:\n");
    printf("--------------------\n");

    // Test empty stack
    printf("Pushing items onto the stack...\n");
    stack_push(&my_stack, 10);
    stack_push(&my_stack, 20);
    stack_push(&my_stack, 30);
    stack_print(&my_stack);

    // Test peek
    int top_value;
    if (stack_peek(&my_stack, &top_value)) {
        printf("Top value is: %d\n", top_value);
    }

    // Test full stack
    printf("\nAttempting to push to a full stack...\n");
    for (int i = 40; i <= 70; i += 10) {
        if (stack_push(&my_stack, i)) {
            stack_print(&my_stack);
        } else {
            printf("Stack is full! Couldn't push %d\n", i);
        }
    }

    // Test pop
    printf("\nPopping items from the stack...\n");
    while (!stack_is_empty(&my_stack)) {
        if (stack_pop(&my_stack, &top_value)) {
            printf("Popped: %d\n", top_value);
            stack_print(&my_stack);
        }
    }

    // Test empty stack
    printf("\nAttempting to pop from an empty stack...\n");
    if (!stack_pop(&my_stack, &top_value)) {
        printf("Stack is empty! Couldn't pop.\n");
    }

    // Test edge cases
    printf("\nTesting edge cases:\n");
    Stack empty_stack;
    stack_init(&empty_stack);
    assert(stack_is_empty(&empty_stack));
    assert(!stack_is_full(&empty_stack));

    Stack full_stack;
    stack_init(&full_stack);
    for (int i = 0; i < STACK_SIZE; i++) {
        stack_push(&full_stack, i);
    }
    assert(stack_is_full(&full_stack));
    assert(!stack_is_empty(&full_stack));

    printf("All tests passed successfully!\n");

    return 0;
}

