#include <stdio.h>
#include <limits.h>

void find_min_max(const int arr[], size_t size, int *min, int *max) {
    if (size == 0) {
        *min = *max = 0; // Undefined behavior if array is empty, handle as needed
        return;
    }

    *min = arr[0];
    *max = arr[0];

    for (size_t i = 1; i < size; i++) {
        if (arr[i] < *min) {
            *min = arr[i];
        } else if (arr[i] > *max) {
            *max = arr[i];
        }
    }
}

int main(void) {
    // Example array
    int arr[] = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
    size_t size = sizeof(arr) / sizeof(arr[0]);

    int min, max;

    find_min_max(arr, size, &min, &max);

    printf("Array: ");
    for (size_t i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    printf("Smallest element: %d\n", min);
    printf("Largest element: %d\n", max);

    return 0;
}

#include <stdio.h>
