#include <stdbool.h>
#include <string.h>

bool is_palindrome(const char *str) {
    int left = 0;
    int right = strlen(str) - 1;

    while (left < right) {
        // Skip non-alphanumeric characters from left
        while (left < right && !isalnum(str[left])) {
            left++;
        }
        // Skip non-alphanumeric characters from right
        while (left < right && !isalnum(str[right])) {
            right--;
        }

        // Compare characters (case-insensitive)
        if (tolower(str[left]) != tolower(str[right])) {
            return false;
        }

        left++;
        right--;
    }

    return true;
}

int main(void) {
    const char *test_string = "A man, a plan, a canal: Panama";

    if (is_palindrome(test_string)) {
        printf("\"%s\" is a palindrome.\n", test_string);
    } else {
        printf("\"%s\" is NOT a palindrome.\n", test_string);
    }

    return 0;
}

#include <stdio.h>
#include <ctype.h>

void decimal_to_hex(unsigned int num) {
    const char hex_digits[] = "0123456789ABCDEF";
    char hex_str[sizeof(unsigned int) * 2 + 1]; // +1 for null terminator
    int i = 0;

    // Handle the case where num is 0
    if (num == 0) {
        putchar('0');
        return;
    }

    // Convert the number to hexadecimal
    while (num > 0) {
        hex_str[i++] = hex_digits[num % 16];
        num /= 16;
    }

    // The digits were stored in reverse order, so reverse them
    for (int j = i - 1; j >= 0; j--) {
        putchar(hex_str[j]);
    }
}

int main() {
    unsigned int decimal_num;

    printf("Enter a decimal number: ");
    scanf("%u", &decimal_num);

    printf("Hexadecimal: ");
    decimal_to_hex(decimal_num);
    putchar('\n');

    return 0;
}

