// Custom implementation of strlen
size_t my_strlen(const char *str) {
    size_t length = 0;
    while (str[length] != '\0') {
        length++;
    }
    return length;
}

// Custom implementation of strcmp
int my_strcmp(const char *str1, const char *str2) {
    while (*str1 != '\0' && *str2 != '\0') {
        if (*str1 != *str2) {
            return (unsigned char)*str1 - (unsigned char)*str2;
        }
        str1++;
        str2++;
    }

    // If we get here, either both strings are equal or one is a prefix of the other
    return (unsigned char)*str1 - (unsigned char)*str2;
}

// Helper function to demonstrate string comparison
void demonstrate_strcmp(const char *str1, const char *str2) {
    int result = my_strcmp(str1, str2);

    printf("Comparing \"%s\" and \"%s\": ", str1, str2);

    if (result < 0) {
        printf("str1 is less than str2\n");
    } else if (result > 0) {
        printf("str1 is greater than str2\n");
    } else {
        printf("strings are equal\n");
    }
}

int main(void) {
    // Test strings
    const char *test1 = "Hello";
    const char *test2 = "World";
    const char *test3 = "Hello";
    const char *test4 = "";
    const char *test5 = "Hello World";
    const char *test6 = "Hello World!";

    // Demonstrate strlen
    printf("String length demonstrations:\n");
    printf("\"%s\" has length %zu\n", test1, my_strlen(test1));
    printf("\"%s\" has length %zu\n", test2, my_strlen(test2));
    printf("\"%s\" has length %zu\n", test3, my_strlen(test3));
    printf("\"%s\" has length %zu\n", test4, my_strlen(test4));
    printf("\"%s\" has length %zu\n", test5, my_strlen(test5));
    printf("\"%s\" has length %zu\n", test6, my_strlen(test6));

    printf("\nString comparison demonstrations:\n");
    demonstrate_strcmp(test1, test2);  // "Hello" vs "World"
    demonstrate_strcmp(test1, test3);  // "Hello" vs "Hello"
    demonstrate_strcmp(test2, test1);  // "World" vs "Hello"
    demonstrate_strcmp(test4, test1);  // "" vs "Hello"
    demonstrate_strcmp(test5, test6);  // "Hello World" vs "Hello World!"
    demonstrate_strcmp(test6, test5);  // "Hello World!" vs "Hello World"

    return 0;
}

