#include <stdio.h>

/**
 * @brief Performs binary search on a sorted array of integers.
 *
 * @param arr The sorted array to search in.
 * @param size The number of elements in the array.
 * @param target The value to search for.
 * @return int The index of the target if found, otherwise -1.
 */
int binary_search(const int arr[], size_t size, int target) {
    int left = 0;
    int right = (int)size - 1;  // Cast to int since size_t might be larger

    while (left <= right) {
        int mid = left + (right - left) / 2;  // Prevents potential overflow

        if (arr[mid] == target) {
            return mid;  // Target found
        } else if (arr[mid] < target) {
            left = mid + 1;  // Search the right half
        } else {
            right = mid - 1;  // Search the left half
        }
    }

    return -1;  // Target not found
}

int main(void) {
    // Example sorted array
