#include <iostream>
#include <string>
#include <algorithm> // For std::swap (though we'll implement our own for C++98)

void reverseStringInPlace(std::string& str) {
    // Iterate from the start to the middle of the string
    for (size_t i = 0; i < str.length() / 2; ++i) {
        // Swap characters from the start and end moving towards the center
        char temp = str[i];
        str[i] = str[str.length() - 1 - i];
        str[str.length() - 1 - i] = temp;
    }
}

int main() {
    std::string input;

    std::cout << "Enter a string: ";
    std::getline(std::cin, input);

    reverseStringInPlace(input);

    std::cout << "Reversed string: " << input << std::endl;

    return 0;
}

#include <iostream>
#include <cmath>

// Base Shape class
class Shape {
public:
    virtual double area() const = 0;  // Pure virtual function
    virtual ~Shape() {}                // Virtual destructor for proper cleanup
};

// Circle class
class Circle : public Shape {
private:
    double radius;
public:
    Circle(double r) : radius(r) {}
    double area() const {
        return M_PI * radius * radius;
    }
};

// Square class
class Square : public Shape {
private:
    double side;
public:
    Square(double s) : side(s) {}
    double area() const {
        return side * side;
    }
};

// Function to print area through base pointer
void printArea(const Shape* shape) {
    std::cout << "Area: " << shape->area() << std::endl;
}

int main() {
    // Create objects using derived classes
    Circle circle(5.0);
    Square square(4.0);

    // Store in base class pointers
    Shape* shapes[2];
    shapes[0] = &circle;
    shapes[1] = &square;

    // Print areas through base pointers
    for (int i = 0; i < 2; ++i) {
        std::cout << "Shape " << i+1 << ": ";
        printArea(shapes[i]);
    }

    return 0;
}

