// Template function to find the maximum of three values
template <typename T>
T max3(T a, T b, T c) {
    T max_val = a;
    if (b > max_val) {
        max_val = b;
    }
    if (c > max_val) {
        max_val = c;
    }
    return max_val;
}

int main() {
    // Demonstration with int
    int int1 = 5, int2 = 12, int3 = 8;
    int max_int = max3(int1, int2, int3);
    std::cout << "The maximum of " << int1 << ", " << int2 << ", and " << int3
              << " is: " << max_int << std::endl;

    // Demonstration with double
    double dbl1 = 3.14, dbl2 = 2.71, dbl3 = 1.618;
    double max_dbl = max3(dbl1, dbl2, dbl3);
    std::cout << "The maximum of " << dbl1 << ", " << dbl2 << ", and " << dbl3
              << " is: " << max_dbl << std::endl;

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <sstream>

std::vector<std::string> split(const std::string &s, char delimiter) {
    std::vector<std::string> tokens;
    std::string token;
    std::istringstream tokenStream(s);

    while (std::getline(tokenStream, token, delimiter)) {
        tokens.push_back(token);
    }

    return tokens;
}

int main() {
    std::string input;
    std::cout << "Enter a comma-separated string: ";
    std::getline(std::cin, input);

    std::vector<std::string> tokens = split(input, ',');

    std::cout << "Tokens:" << std::endl;
    for (size_t i = 0; i < tokens.size(); ++i) {
        std::cout << i + 1 << ": " << tokens[i] << std::endl;
    }

    return 0;
}

#include <iostream>

// Define the Point struct
struct Point {
    int x;
    int y;

    // Constructor
    Point(int x = 0, int y = 0) : x(x), y(y) {}

    // Overload the + operator to add two points
    Point operator+(const Point& other) const {
        return Point(x + other.x, y + other.y);
    }

    // Overload the == operator to compare two points
    bool operator==(const Point& other) const {
        return (x == other.x) && (y == other.y);
    }
};

// Demonstration function
void demonstratePointOperations() {
    // Create some points
    Point p1(3, 4);
    Point p2(1, 2);
    Point p3;

    // Demonstrate operator+
    std::cout << "Demonstrating operator+:" << std::endl;
    p3 = p1 + p2;
    std::cout << "p1 + p2 = (" << p3.x << ", " << p3.y << ")" << std::endl;

    // Demonstrate operator==
    std::cout << "\nDemonstrating operator=:" << std::endl;
    std::cout << "p1 == p2: " << (p1 == p2 ? "true" : "false") << std::endl;
    std::cout << "p1 == p3: " << (p1 == p3 ? "true" : "false") << std::endl;

    // Demonstrate chaining
    std::cout << "\nDemonstrating chaining:" << std::endl;
    Point p4 = p1 + p2 + Point(5, 6);
    std::cout << "p1 + p2 + (5,6) = (" << p4.x << ", " << p4.y << ")" << std::endl;
}

int main() {
    demonstratePointOperations();
    return 0;
}

