#include <iostream>

class ScopePrinter {
public:
    // Constructor - prints when object is created
    ScopePrinter(const char* name) {
        std::cout << "Entering scope: " << name << std::endl;
    }

    // Destructor - prints when object goes out of scope
    ~ScopePrinter() {
        std::cout << "Exiting scope" << std::endl;
    }

    // Delete copy constructor and assignment operator to prevent copying
    ScopePrinter(const ScopePrinter&);
    ScopePrinter& operator=(const ScopePrinter&);
};

// Define the deleted functions
ScopePrinter::ScopePrinter(const ScopePrinter&) {}
ScopePrinter& ScopePrinter::operator=(const ScopePrinter&) { return *this; }

int main() {
    {
        std::cout << "--- Block 1 ---" << std::endl;
        ScopePrinter printer1("Block 1");
        // printer1 goes out of scope at end of block
    } // Destructor called here

    {
        std::cout << "\n--- Block 2 ---" << std::endl;
        {
            ScopePrinter printer2("Inner Block");
            // printer2 goes out of scope at end of inner block
        } // Destructor called here
        // printer2 is not accessible here
    } // No destructor for printer2 here (already called)

    {
        std::cout << "\n--- Block 3 ---" << std::endl;
        ScopePrinter printer3("Block 3");
        // printer3 will go out of scope at end of block
    } // Destructor called here

    std::cout << "\n--- End of main ---" << std::endl;
    return 0;
}

