#include <iostream>
#include <vector>
#include <stdexcept> // For std::out_of_range

template <typename T>
class Stack {
private:
    std::vector<T> data;

public:
    // Push an element onto the stack
    void push(const T& value) {
        data.push_back(value);
    }

    // Remove the top element from the stack
    void pop() {
        if (data.empty()) {
            throw std::out_of_range("Stack is empty");
        }
        data.pop_back();
    }

    // Get the top element of the stack
    T& top() {
        if (data.empty()) {
            throw std::out_of_range("Stack is empty");
        }
        return data.back();
    }

    // Check if the stack is empty
    bool empty() const {
        return data.empty();
    }

    // Get the number of elements in the stack
    size_t size() const {
        return data.size();
    }
};

int main() {
    // Demonstration of the Stack class
    Stack<int> intStack;

    // Push elements onto the stack
    intStack.push(10);
    intStack.push(20);
    intStack.push(30);

    std::cout << "Stack size: " << intStack.size() << std::endl; // Output: 3

    // Access the top element
    std::cout << "Top element: " << intStack.top() << std::endl; // Output: 30

    // Pop elements from the stack
    intStack.pop();
    std::cout << "Top element after pop: " << intStack.top() << std::endl; // Output: 20

    // Check if the stack is empty
    std::cout << "Is stack empty? " << (intStack.empty() ? "Yes" : "No") << std::endl; // Output: No

    // Pop all elements
    intStack.pop();
    intStack.pop();
    std::cout << "Is stack empty now? " << (intStack.empty() ? "Yes" : "No") << std::endl; // Output: Yes

    // Try to pop from an empty stack (will throw an exception)
    try {
        intStack.pop();
    } catch (const std::out_of_range& e) {
        std::cerr << "Error: " << e.what() << std::endl; // Output: Error: Stack is empty
    }

    // Demonstrate with strings
    Stack<std::string> stringStack;
    stringStack.push("Hello");
    stringStack.push("World");

    std::cout << "String stack top: " << stringStack.top() << std::endl; // Output: World

    return 0;
}

