#include <iostream>
#include <stdexcept> // For std::runtime_error

class BankAccount {
private:
    double balance;

public:
    // Constructor
    BankAccount(double initialBalance = 0.0)
        : balance(initialBalance) {
        if (initialBalance < 0) {
            throw std::runtime_error("Initial balance cannot be negative");
        }
    }

    // Deposit money
    void deposit(double amount) {
        if (amount <= 0) {
            throw std::runtime_error("Deposit amount must be positive");
        }
        balance += amount;
    }

    // Withdraw money
    void withdraw(double amount) {
        if (amount <= 0) {
            throw std::runtime_error("Withdrawal amount must be positive");
        }
        if (amount > balance) {
            throw std::runtime_error("Insufficient funds");
        }
        balance -= amount;
    }

    // Get current balance
    double getBalance() const {
        return balance;
    }

    // Display balance
    void displayBalance() const {
        std::cout << "Current balance: $" << balance << std::endl;
    }
};

int main() {
    try {
        // Create an account with initial balance of $100
        BankAccount account(100.0);

        // Display initial balance
        account.displayBalance();

        // Deposit $50
        account.deposit(50.0);
        account.displayBalance();

        // Withdraw $30
        account.withdraw(30.0);
        account.displayBalance();

        // Try to withdraw more than balance (will throw exception)
        // account.withdraw(200.0);

        // Try to deposit negative amount (will throw exception)
        // account.deposit(-10.0);

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}

