// Template function to find the maximum of three values
template <typename T>
T max3(T a, T b, T c) {
    T max_val = a;
    if (b > max_val) {
        max_val = b;
    }
    if (c > max_val) {
        max_val = c;
    }
    return max_val;
}

int main() {
    // Demonstrate with int
    int int1 = 5, int2 = 10, int3 = 7;
    int max_int = max3(int1, int2, int3);
    std::cout << "Maximum of " << int1 << ", " << int2 << ", " << int3
              << " is: " << max_int << std::endl;

    // Demonstrate with double
    double d1 = 3.14, d2 = 2.71, d3 = 1.618;
    double max_double = max3(d1, d2, d3);
    std::cout << "Maximum of " << d1 << ", " << d2 << ", " << d3
              << " is: " << max_double << std::endl;

    // Optional: Demonstrate with other types (e.g., char)
    char c1 = 'a', c2 = 'z', c3 = 'm';
    char max_char = max3(c1, c2, c3);
    std::cout << "Maximum of '" << c1 << "', '" << c2 << "', '" << c3
              << "' is: '" << max_char << "' (ASCII: " << static_cast<int>(max_char) << ")" << std::endl;

    return 0;
}

#include <iostream>
