#include <iostream>
#include <string>

class ScopedMessage {
public:
    // Constructor - prints message when object is created
    explicit ScopedMessage(const std::string& message)
        : message_(message)
    {
        std::cout << "[Constructed] " << message_ << std::endl;
    }

    // Destructor - prints message when object goes out of scope
    ~ScopedMessage() {
        std::cout << "[Destroyed] " << message_ << std::endl;
    }

    // Delete copy constructor and assignment operator to prevent copying
    ScopedMessage(const ScopedMessage&) = delete;
    ScopedMessage& operator=(const ScopedMessage&) = delete;

private:
    std::string message_;
};

void demonstrateScope() {
    // Local scope - object will be destroyed at end of this block
    {
        std::cout << "Entering inner scope" << std::endl;
        ScopedMessage msg1("First message in inner scope");

        // Another object in the same scope
        ScopedMessage msg2("Second message in inner scope");

        std::cout << "Exiting inner scope" << std::endl;
    } // msg1 and msg2 will be destroyed here

    // Object in outer scope
    ScopedMessage msg3("Message in outer scope");
}

int main() {
    std::cout << "Starting program" << std::endl;

    // Object in main scope
    ScopedMessage mainMsg("Main function message");

    // Function call with its own scope
    demonstrateScope();

    std::cout << "Exiting program" << std::endl;

    return 0;
}

