#include <iostream>
#include <vector>
#include <stdexcept> // For std::out_of_range

template <typename T>
class Stack {
private:
    std::vector<T> elements;

public:
    // Push an element onto the stack
    void push(const T& value) {
        elements.push_back(value);
    }

    // Remove the top element from the stack
    void pop() {
        if (elements.empty()) {
            throw std::out_of_range("Stack is empty - cannot pop");
        }
        elements.pop_back();
    }

    // Get the top element without removing it
    T& top() {
        if (elements.empty()) {
            throw std::out_of_range("Stack is empty - cannot access top");
        }
        return elements.back();
    }

    // Check if the stack is empty
    bool empty() const {
        return elements.empty();
    }

    // Get the number of elements in the stack
    size_t size() const {
        return elements.size();
    }
};

int main() {
    // Demonstration of the Stack class
    Stack<int> intStack;

    std::cout << "Pushing elements onto the stack...\n";
    for (int i = 1; i <= 5; ++i) {
        intStack.push(i * 10);
        std::cout << "Pushed: " << i * 10 << "\n";
    }

    std::cout << "\nStack size: " << intStack.size() << "\n";

    std::cout << "\nPopping elements from the stack...\n";
    while (!intStack.empty()) {
        std::cout << "Top element: " << intStack.top() << "\n";
        intStack.pop();
    }

    std::cout << "\nAttempting to pop from empty stack...\n";
    try {
        intStack.pop();
    } catch (const std::out_of_range& e) {
        std::cout << "Error: " << e.what() << "\n";
    }

    // Demonstration with strings
    std::cout << "\n\nDemonstrating with strings...\n";
    Stack<std::string> stringStack;
    stringStack.push("Hello");
    stringStack.push("World");
    stringStack.push("C++");

    std::cout << "Top string: " << stringStack.top() << "\n";
    stringStack.pop();
    std::cout << "New top string: " << stringStack.top() << "\n";

    return 0;
}

