#include <iostream>
#include <stdexcept> // For std::invalid_argument

class BankAccount {
private:
    std::string accountHolder;
    double balance;

public:
    // Constructor
    BankAccount(const std::string& holder, double initialBalance = 0.0)
        : accountHolder(holder), balance(initialBalance) {
        if (initialBalance < 0) {
            throw std::invalid_argument("Initial balance cannot be negative");
        }
    }

    // Deposit money
    void deposit(double amount) {
        if (amount <= 0) {
            throw std::invalid_argument("Deposit amount must be positive");
        }
        balance += amount;
    }

    // Withdraw money
    void withdraw(double amount) {
        if (amount <= 0) {
            throw std::invalid_argument("Withdrawal amount must be positive");
        }
        if (amount > balance) {
            throw std::runtime_error("Insufficient funds for withdrawal");
        }
        balance -= amount;
    }

    // Get current balance
    double getBalance() const {
        return balance;
    }

    // Get account holder name
    std::string getAccountHolder() const {
        return accountHolder;
    }

    // Display account information
    void display() const {
        std::cout << "Account Holder: " << accountHolder << "\n"
                  << "Current Balance: $" << balance << "\n";
    }
};

int main() {
    try {
        // Create a bank account
        BankAccount account("John Doe", 1000.0);

        // Display initial balance
        std::cout << "Initial account information:\n";
        account.display();

        // Perform some transactions
        account.deposit(500.0);
        std::cout << "\nAfter depositing $500:\n";
        account.display();

        account.withdraw(200.0);
        std::cout << "\nAfter withdrawing $200:\n";
        account.display();

        // This will throw an exception
        // account.withdraw(2000.0);

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}

