#include <iostream>
#include <string>

class ScopedMessage {
public:
    // Constructor - prints message when object is created
    ScopedMessage(const std::string& message)
        : message_(message)
    {
        std::cout << "[Constructed] " << message_ << std::endl;
    }

    // Destructor - prints message when object goes out of scope
    ~ScopedMessage() {
        std::cout << "[Destroyed] " << message_ << std::endl;
    }

    // Delete copy operations to prevent accidental copies
    ScopedMessage(const ScopedMessage&) = delete;
    ScopedMessage& operator=(const ScopedMessage&) = delete;

private:
    std::string message_;
};

void demonstrateScope() {
    // Local scope - object will be destroyed at end of this block
    {
        std::cout << "Entering inner scope" << std::endl;
        ScopedMessage msg1("Inner scope message");
        // msg1 will be destroyed here when scope ends
    }

    std::cout << "Exiting inner scope" << std::endl;

    // Another scope
    {
        ScopedMessage msg2("Another scope message");
        // msg2 will be destroyed here
    }

    // This will be destroyed at end of function
    ScopedMessage msg3("Function scope message");
}

int main() {
    std::cout << "=== Starting program ===" << std::endl;

    // Demonstrate scope-based lifetime
    {
        std::cout << "Entering main scope" << std::endl;
        ScopedMessage msg("Main scope message");
        demonstrateScope();
        // msg will be destroyed here
    }

    std::cout << "Exiting main scope" << std::endl;
    std::cout << "=== Program ending ===" << std::endl;

    return 0;
}

#include <iostream>
