int main() {
    // Define the dimensions of the grid
    const int rows = 4;
    const int cols = 5;

    // Create a 2D vector grid initialized with zeros
    std::vector<std::vector<int>> grid(rows, std::vector<int>(cols, 0));

    // Fill the grid with some values (example: row-major order)
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
