#include <iostream>
#include <array>
#include <string>

int main() {
    // Hardcoded number
    const std::string number = "12345678901234567890";

    // Initialize frequency array with 10 zeros (for digits 0-9)
    std::array<int, 10> frequency = {0};

    // Count frequency of each digit
    for (char c : number) {
        if (isdigit(c)) {  // Check if it's a digit character
            int digit = c - '0';  // Convert char to digit value
            frequency[digit]++;
        }
    }

    // Print the histogram
    std::cout << "Digit frequency histogram for: " << number << "\n\n";

    for (int i = 0; i < 10; ++i) {
        std::cout << "Digit " << i << ": ";

        // Print the count
        std::cout << frequency[i] << " | ";

        // Print the bar
        std::cout << std::string(frequency[i], '*') << "\n";
    }

    return 0;
}

