#include <iostream>
#include <format> // C++20 feature for formatted output

class Rectangle {
private:
    double width;
    double height;

public:
    // Constructor
    Rectangle(double w, double h) : width(w), height(h) {}

    // Getter methods
    double getWidth() const { return width; }
    double getHeight() const { return height; }

    // Method to calculate area
    double area() const {
        return width * height;
    }

    // Optional: Setter methods
    void setWidth(double w) { width = w; }
    void setHeight(double h) { height = h; }
};

int main() {
    // Create a rectangle with width 5.0 and height 3.0
    Rectangle rect1(5.0, 3.0);

    // Print rectangle details using C++20 formatted output
    std::cout << std::format("Rectangle 1 - Width: {:.2f}, Height: {:.2f}, Area: {:.2f}\n",
                            rect1.getWidth(), rect1.getHeight(), rect1.area());

    // Create another rectangle with width 4.5 and height 2.0
    Rectangle rect2(4.5, 2.0);

    // Print rectangle details
    std::cout << std::format("Rectangle 2 - Width: {:.2f}, Height: {:.2f}, Area: {:.2f}\n",
                            rect2.getWidth(), rect2.getHeight(), rect2.area());

    // Modify rectangle 1's dimensions and print again
    rect1.setWidth(7.0);
    rect1.setHeight(4.0);
    std::cout << std::format("Modified Rectangle 1 - Width: {:.2f}, Height: {:.2f}, Area: {:.2f}\n",
                            rect1.getWidth(), rect1.getHeight(), rect1.area());

    return 0;
}

