#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

std::vector<std::string> split_csv(const std::string& str) {
    std::vector<std::string> tokens;
    std::stringstream ss(str);
    std::string token;

    // Split by comma, trimming whitespace
    while (std::getline(ss, token, ',')) {
        // Trim leading and trailing whitespace from each token
        token.erase(token.begin(), std::find_if(token.begin(), token.end(), [](int ch) { return !std::isspace(ch); }));
        token.erase(std::find_if(token.rbegin(), token.rend(), [](int ch) { return !std::isspace(ch); }).base(), token.end());

        if (!token.empty()) {
            tokens.push_back(token);
        }
    }

    return tokens;
}

int main() {
    std::string input = "apple, banana,  cherry,  ,  date,  ,  elderberry";

    std::cout << "Original string: \"" << input << "\"\n";
    std::cout << "Tokens:\n";

    auto tokens = split_csv(input);
    for (const auto& token : tokens) {
        std::cout << "  - \"" << token << "\"\n";
    }

    return 0;
}

#include <iostream>
#include <cassert>

// Define a Point struct with x and y coordinates
struct Point {
    double x;
    double y;

    // Constructor (optional but useful)
    Point(double x = 0.0, double y = 0.0) : x(x), y(y) {}

    // Overload the + operator to add two Points
    Point operator+(const Point& other) const {
        return Point(x + other.x, y + other.y);
    }

    // Overload the == operator to compare two Points
    bool operator==(const Point& other) const {
        return (x == other.x) && (y == other.y);
    }
};

// Demonstration of the Point struct and its operators
int main() {
    // Create some Point objects
    Point p1(3.0, 4.0);
    Point p2(1.0, 2.0);
    Point p3;

    // Demonstrate operator+
    p3 = p1 + p2;  // p3 should now be (4.0, 6.0)
    std::cout << "p1 + p2 = (" << p3.x << ", " << p3.y << ")\n";

    // Demonstrate operator==
    assert((p1 + p2) == Point(4.0, 6.0));  // Should pass
    assert(p1 != p2);  // Should pass (p1 is (3,4), p2 is (1,2))

    // Demonstrate with default constructor
    Point p4;
    Point p5(0.0, 0.0);
    assert(p4 == p5);  // Should pass (both are (0,0))

    std::cout << "All tests passed successfully!\n";
    return 0;
}

