#include <iostream>
#include <vector>
#include <stdexcept>
#include <concepts>

template <typename T>
class Stack {
private:
    std::vector<T> data;

public:
    // Default constructor
    Stack() = default;

    // Copy constructor
    Stack(const Stack& other) = default;

    // Move constructor
    Stack(Stack&& other) noexcept = default;

    // Copy assignment
    Stack& operator=(const Stack& other) = default;

    // Move assignment
    Stack& operator=(Stack&& other) noexcept = default;

    // Push element onto the stack
    void push(const T& value) {
        data.push_back(value);
    }

    // Push element using move semantics
    void push(T&& value) {
        data.push_back(std::move(value));
    }

    // Pop element from the stack
    void pop() {
        if (data.empty()) {
            throw std::out_of_range("Stack is empty");
        }
        data.pop_back();
    }

    // Get the top element
    T& top() {
        if (data.empty()) {
            throw std::out_of_range("Stack is empty");
        }
        return data.back();
    }

    // Const version of top()
    const T& top() const {
        if (data.empty()) {
            throw std::out_of_range("Stack is empty");
        }
        return data.back();
    }

    // Check if stack is empty
    bool empty() const {
        return data.empty();
    }

    // Get the number of elements
    size_t size() const {
        return data.size();
    }

    // Clear the stack
    void clear() {
        data.clear();
    }
};

// Demonstration of the Stack class
int main() {
    // Create a stack of integers
    Stack<int> intStack;

    // Push some values
    intStack.push(10);
    intStack.push(20);
    intStack.push(30);

    std::cout << "Stack size: " << intStack.size() << std::endl;
    std::cout << "Top element: " << intStack.top() << std::endl;

    // Pop elements
    std::cout << "Popping: " << intStack.top() << std::endl;
    intStack.pop();

    std::cout << "New top element: " << intStack.top() << std::endl;
    intStack.pop();

    // Demonstrate move semantics
    Stack<std::string> strStack;
    strStack.push("Hello");
    strStack.push("World");

    Stack<std::string> movedStack = std::move(strStack);
    std::cout << "\nAfter move: strStack size = " << strStack.size()
              << ", movedStack size = " << movedStack.size() << std::endl;

    // Demonstrate exception handling
    try {
        Stack<int> emptyStack;
        std::cout << emptyStack.top() << std::endl; // This will throw
    } catch (const std::out_of_range& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}

#include <iostream>
#include <string>
#include <unordered_set>

int count_vowels(const std::string& str) {
    // Define vowels (case-insensitive)
    const std::unordered_set<char> vowels = {'a', 'e', 'i', 'o', 'u'};

    int count = 0;
    for (char c : str) {
        // Convert to lowercase for case-insensitive comparison
        char lower_c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        if (vowels.find(lower_c) != vowels.end()) {
            ++count;
        }
    }
    return count;
}

int main() {
    std::string input;
    std::cout << "Enter a string: ";
    std::getline(std::cin, input);

    int vowel_count = count_vowels(input);
    std::cout << "Number of vowels: " << vowel_count << std::endl;

    return 0;
}

