#include <iostream>
#include <stdexcept>
#include <string>
#include <format> // C++20 feature

class BankAccount {
private:
    std::string accountHolder;
    double balance;

public:
    // Constructor
    BankAccount(const std::string& holder, double initialBalance = 0.0)
        : accountHolder(holder), balance(initialBalance) {
        if (initialBalance < 0) {
            throw std::invalid_argument("Initial balance cannot be negative");
        }
    }

    // Deposit money
    void deposit(double amount) {
        if (amount <= 0) {
            throw std::invalid_argument("Deposit amount must be positive");
        }
        balance += amount;
    }

    // Withdraw money
    void withdraw(double amount) {
        if (amount <= 0) {
            throw std::invalid_argument("Withdrawal amount must be positive");
        }
        if (amount > balance) {
            throw std::runtime_error("Insufficient funds");
        }
        balance -= amount;
    }

    // Get current balance
    double getBalance() const {
        return balance;
    }

    // Print account information
    void printBalance() const {
        std::cout << std::format("Account Holder: {}\n", accountHolder);
        std::cout << std::format("Current Balance: ${:.2f}\n", balance);
    }
};

int main() {
    try {
        // Create a bank account
        BankAccount account("John Doe", 1000.00);

        // Print initial balance
        account.printBalance();

        // Perform some transactions
        account.deposit(500.00);
        std::cout << "\nAfter depositing $500:\n";
        account.printBalance();

        account.withdraw(200.00);
        std::cout << "\nAfter withdrawing $200:\n";
        account.printBalance();

        // This will throw an exception
        // account.withdraw(2000.00);

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}

