#include <iostream>
#include <array>
#include <algorithm>
#include <string>

int main() {
    // Hardcoded number (can be changed to any number)
    const std::string number = "12345678901234567890";

    // Initialize frequency array with 10 zeros (for digits 0-9)
    std::array<int, 10> digit_counts{};

    // Count each digit's frequency
    for (char c : number) {
        if (isdigit(c)) {
            digit_counts[c - '0']++;
        }
    }

    // Find the maximum count for scaling the histogram
    int max_count = *std::max_element(digit_counts.begin(), digit_counts.end());

    // Print the histogram
    std::cout << "Digit frequency histogram for: " << number << "\n\n";

    for (int i = 0; i < 10; ++i) {
        // Print digit and its count
        std::cout << "Digit " << i << ": " << digit_counts[i] << " ("
                  << static_cast<double>(digit_counts[i]) / number.size() * 100
                  << "%)";

        // Print the bar
        if (max_count > 0) {
            int bar_length = static_cast<int>(20 * digit_counts[i] / max_count);
            std::cout << " [";
            std::cout << std::string(bar_length, '#');
            std::cout << "]";
        }

        std::cout << "\n";
    }

    return 0;
}
